    return "document" if track == "documents" else "learned_qa"

MERGE_JUDGE_PROMPT = 'You are a faithfulness judge for a chunk-merging step.\n\nThe merging step received several near-duplicate SOURCE CHUNKS and produced one MERGED CHUNK.\nYour job is to verify that the MERGED CHUNK is faithful: it must not invent facts, and it must\npreserve every substantive fact from the source chunks.\n\nCRITICAL RULES FOR JUDGING FACTS:\nRULE 1 - PARAPHRASE = PRESENT\nIf two source chunks state the same fact in different words, and the merged chunk expresses\nthat fact ONCE (in any wording), the fact is PRESERVED for BOTH source chunks.\nDo NOT list it as dropped just because one source\'s exact wording is absent.\nRULE 2 - DEDUPLICATE BEFORE CHECKING\nMultiple source chunks often overlap heavily. Before listing a dropped fact, confirm that\nthe underlying information is genuinely absent from the merged chunk - not merely rephrased.\nRULE 3 - IGNORE FORMATTING\nCitation tags like "[Source: filename]", inline references, and sentence order changes are\nformatting choices, not factual differences. Never treat them as fabrication or omission.\nRULE 4 - SUBSTANTIVE FACTS ONLY\nOnly flag facts with meaningful informational content. Generic connector phrases, filler\nsentences, and stylistic differences are NOT facts and must never appear in either list.\n\nSOURCE CHUNKS (the only allowed evidence):\n{sources_block}\n\nMERGED CHUNK (the output to validate):\n{merged_block}\n\nPROCESS (follow in this exact order):\n1. CHECK FOR FABRICATION - For every factual claim in the MERGED CHUNK, ask: "Is this claim\n   supported by at least one SOURCE CHUNK above - either verbatim or as a clear paraphrase?"\n   - If YES -> the claim is supported. Do NOT list it.\n   - If NO  -> list it in "fabricated_claims".\n2. CHECK FOR DROPPED FACTS - Collect every distinct substantive fact from ALL source chunks.\n   For each fact, ask: "Does the MERGED CHUNK express this fact - verbatim OR as a paraphrase?"\n   - If YES -> the fact is preserved. Do NOT list it.\n   - If NO  -> list it in "dropped_claims".\n\nOUTPUT FORMAT\nReturn ONLY a JSON object - no markdown, no code fences, no prose outside the JSON.\n{{\n  "fabricated_claims": ["<exact claim from merged chunk that has no source support>", ...],\n  "dropped_claims":    ["<substantive fact from sources genuinely absent from merged chunk>", ...],\n  "overall_reason": "<one or two sentences explaining your verdict>"\n}}\nIf both lists are empty, return empty arrays. Do not invent items to fill them.\n'


class RagNacValidator(Component):
    display_name = "validate_NAC_documents"
    description = (
        "validate_nac_documents in nac.py. Runs the faithfulness judge over every neighbour "
        "run NAC merged and records the verdicts. Observational, like the LangGraph node - "
        "the chunks are not modified."
    )
    icon = "shield-check"
    name = "RagNacValidator"

    inputs = [
        DataInput(name="state", display_name="State", is_list=True),
        HandleInput(
            name="llm",
            display_name="Judge Model",
            input_types=["LanguageModel"],
            required=True,
            info="judge_llm in llm_setup.py: temperature 0.0, 1024 output tokens.",
        ),
        HandleInput(
            name="repair_llm",
            display_name="JSON Repair Model",
            input_types=["LanguageModel"],
            required=False,
            info="Groq client used only to repair malformed JSON (temperature 0.0, 1024 tokens).",
        ),
        MultilineInput(name="judge_prompt", display_name="Merge Judge Prompt", value=MERGE_JUDGE_PROMPT),
    ]

    outputs = [Output(display_name="State", name="state_out", method="validate")]

    def validate(self) -> Data:
        state = _state_of(self.state)
        pairs = list(state.get("nac_merge_pairs_documents") or [])
        if not pairs:
            self.status = "no merge pairs to validate"
            return Data(data=state)

        verdicts = []
        for index, pair in enumerate(pairs):
            prompt = self.judge_prompt.format(
                sources_block=_chunks_block(pair.get("source_chunks") or []),
                merged_block=(pair.get("merged") or {}).get("content", ""),
            )
            result = _parse_json(_llm_text(self.llm, prompt), {}, repair_llm=self.repair_llm)
            fabricated = (result or {}).get("fabricated_claims") or [] if isinstance(result, dict) else []
            dropped = (result or {}).get("dropped_claims") or [] if isinstance(result, dict) else []
            verdicts.append(
                {
                    "pair": index,
                    "verdict": "FAIL" if (fabricated or dropped) else "PASS",
                    "fabricated_claims": fabricated,
                    "dropped_claims": dropped,
                }
            )

        state["nac_validation_verdicts"] = verdicts
        self.status = "\n".join(
            "pair {0}: verdict={1}  fabricated={2}  dropped={3}".format(
                entry["pair"], entry["verdict"], len(entry["fabricated_claims"]), len(entry["dropped_claims"])
            )
            for entry in verdicts
        )
        return Data(data=state)

