DC_SCAN_PROMPT = 'You are performing sentence-level redundancy annotation.\n\nYour task:\nIdentify sentences from DIFFERENT chunks that express the SAME FACT.\n\nIMPORTANT:\nTwo sentences are redundant ONLY if they communicate essentially the SAME information.\n\nThe sentences must match on:\n- subject\n- claim\n- meaning\n\nBeing about the SAME TOPIC is NOT enough.\n\nYou are NOT writing software.\nYou are NOT generating Python.\nYou are NOT solving a coding task.\nYou are ONLY selecting matching factual statements.\n\nReturn ONLY a JSON array.\n\nCHUNKS:\n{chunks_block}\n\nWHAT COUNTS AS REDUNDANT:\n- Same fact\n- Same subject\n- Same meaning\n- Paraphrases are allowed\n\nGOOD EXAMPLE:\nChunk 0: "ASD affects 1 in 36 children."\nChunk 1: "Approximately 1 in 36 children have autism."\nThese ARE redundant because they express the same fact.\n\nNOT REDUNDANT - SAME TOPIC BUT DIFFERENT FACTS:\nChunk 0: "ASD patients may experience sensory overload."\nChunk 1: "Healthcare providers should reduce loud noises."\nThese are RELATED but NOT redundant.\n\nNOT REDUNDANT - DIFFERENT SUBJECTS:\nChunk 0: "Dawood\'s policy includes accidents."\nChunk 1: "Umair\'s policy includes accidents."\nDifferent subjects = NOT redundant.\n\nIMPORTANT RULES:\n- A group MUST contain sentences from AT LEAST TWO DIFFERENT chunks.\n- Never group sentences from only one chunk.\n- One shared fact = one group.\n- Copy sentences EXACTLY as written.\n- Do not rewrite sentences.\n- Be CONSERVATIVE. If unsure, DO NOT group.\n- It is BETTER to miss a redundancy than to create a false match.\n\nIf nothing is redundant, return:\n[]\n\nOUTPUT FORMAT:\n[\n  {{\n    "members": [\n      {{"chunk_index": 0, "sentence": "Exact sentence from chunk."}},\n      {{"chunk_index": 1, "sentence": "Matching sentence from another chunk."}}\n    ]\n  }}\n]\n\nThe first character of your response must be \'[\'\nYour response will be parsed directly using json.loads().\nReturn ONLY the JSON array.\n'

_SOURCE_TAG_RE = re.compile(r"\[Source:[^\]]*\]", re.IGNORECASE)


class RagDcCompress(Component):
    display_name = "DC_documents"
    description = (
        "dc.py. Slides a DC_WINDOW_SIZE window over the track and asks the model which "
        "sentences from DIFFERENT chunks state the same fact. Groups must span at least two "
        "distinct chunks; the lowest chunk index in a group keeps the sentence and the others "
        "lose it. A removal that changes nothing, or that would leave under 50 characters, is "
        "skipped."
    )
    icon = "scissors"
    name = "RagDcCompress"

    ROUTES = ("to_validator",)
    MIN_CLEANED_CHARS = 50

    inputs = [
        DataInput(name="state", display_name="State", is_list=True),
        HandleInput(
            name="llm",
            display_name="Generation Model",
            input_types=["LanguageModel"],
            required=True,
            info="llm in llm_setup.py: temperature 0.1, 2048 output tokens.",
        ),
        HandleInput(
            name="repair_llm",
            display_name="JSON Repair Model",
            input_types=["LanguageModel"],
            required=False,
            info="Groq client used only to repair malformed JSON (temperature 0.0, 1024 tokens).",
        ),
        DropdownInput(
            name="track",
            display_name="Track",
            options=["documents", "learned_qa"],
            value="documents",
        ),
        BoolInput(name="enable_dc", display_name="ENABLE_DC_COMPRESSION", value=True),
        IntInput(name="window_size", display_name="DC_WINDOW_SIZE", value=3),
        MultilineInput(name="scan_prompt", display_name="DC Scan Prompt", value=DC_SCAN_PROMPT),
    ]

    outputs = [
        Output(display_name="To Validator", name="to_validator", method="route_validator"),
    ]

    def _input_chunks(self, state):
        if self.track == "documents":
            return list(state.get("nac_output_document_chunks") or [])
        return list(state.get("dedup_merged_learned_qa_chunks") or [])

    @staticmethod
    def _window_block(window):
        blocks = []
        for local_index, chunk in enumerate(window):
            source = chunk.get("source", "?")
            content = _SOURCE_TAG_RE.sub("", (chunk.get("content") or "")).strip()
            blocks.append("--- chunk {0} (source: {1}) ---\n{2}".format(local_index, source, content))
        return "\n\n".join(blocks)

    def _run(self):
        state = _state_of(self.state)
        field = _field(self.track)
        chunks = self._input_chunks(state)

        if not self.enable_dc:
            state["dc_output_{0}_chunks".format(field)] = chunks
            state["dc_groups_per_window_{0}".format(self.track)] = []
            return state, "disabled - passing through {0} chunk(s)".format(len(chunks))

        if len(chunks) < 2:
            state["dc_output_{0}_chunks".format(field)] = list(chunks)
            state["dc_groups_per_window_{0}".format(self.track)] = []
            return state, "fewer than 2 chunks - nothing to scan"

        result = [dict(chunk) for chunk in chunks]
        window_size = max(2, self.window_size)
        groups_per_window = []
        total_removed = 0

        for window_start in range(0, len(result), window_size):
            window = result[window_start:min(window_start + window_size, len(result))]
            if len(window) < 2:
                continue

            prompt = self.scan_prompt.format(chunks_block=self._window_block(window))
            flagged = _parse_json(_llm_text(self.llm, prompt), [], repair_llm=self.repair_llm)
            if not isinstance(flagged, list) or not flagged:
                continue

            valid_groups = []
            for group in flagged:
                members = (group or {}).get("members") if isinstance(group, dict) else None
                if not isinstance(members, list) or len(members) < 2:
                    continue
                clean_members = []
                for member in members:
                    if not isinstance(member, dict):
                        continue
                    local_index = member.get("chunk_index")
                    sentence = (member.get("sentence") or "").strip()
                    if not isinstance(local_index, int) or isinstance(local_index, bool) or not sentence:
                        continue
                    if local_index < 0 or local_index >= len(window):
                        continue
                    clean_members.append({"chunk_index": local_index, "sentence": sentence})
                if len(clean_members) < 2:
                    continue
                # A group must span at least two chunks - intra-chunk repetition is not
                # cross-chunk redundancy.
                if len({member["chunk_index"] for member in clean_members}) < 2:
                    continue
                valid_groups.append(clean_members)

            if not valid_groups:
                continue

            groups_per_window.append({"window_chunks": list(window), "groups": valid_groups})

            # The lowest chunk index keeps the sentence; every other member loses it.
            removals = {}
            for members in valid_groups:
                keeper = min(member["chunk_index"] for member in members)
                for member in members:
                    if member["chunk_index"] != keeper:
                        removals.setdefault(member["chunk_index"], []).append(member["sentence"])

            for local_index, sentences in removals.items():
                global_index = window_start + local_index
                original_chunk = result[global_index]
                original_content = (original_chunk.get("content") or "").strip()

                cleaned = original_content
                for sentence in sentences:
                    if sentence in cleaned:
                        cleaned = cleaned.replace(sentence, "").strip()
                    else:
                        normalised_sentence = " ".join(sentence.split())
                        normalised_content = " ".join(cleaned.split())
                        if normalised_sentence in normalised_content:
                            cleaned = normalised_content.replace(normalised_sentence, "").strip()

                if cleaned == original_content:
                    continue
                if len(cleaned.strip()) < self.MIN_CLEANED_CHARS:
                    continue

                result[global_index] = {**original_chunk, "content": cleaned}
                total_removed += len(sentences)

        state["dc_output_{0}_chunks".format(field)] = result
        state["dc_groups_per_window_{0}".format(self.track)] = groups_per_window
        return state, "{0} redundant passage(s) removed across {1} chunk(s)".format(total_removed, len(result))

    def _emit(self, target):
        state, status = self._run()
        route = "to_validator"
        if route != target:
            self.stop(target)
            return Data(data={})
        for other in self.ROUTES:
            if other != target:
                self.stop(other)
        self.status = "{0} | route={1}".format(status, route)
        return Data(data=state)

    def route_validator(self) -> Data:
        return self._emit("to_validator")

import json
import re

from lfx.custom.custom_component.component import Component
from lfx.io import (
    BoolInput,
    DataInput,
    DropdownInput,
    FloatInput,
    HandleInput,
    IntInput,
    MessageInput,
    MultilineInput,
    Output,
    StrInput,
)
from lfx.schema.data import Data
from lfx.schema.dataframe import DataFrame
from lfx.schema.message import Message


def _state_of(payload):
    """Unwrap a Langflow Data payload (or list of them) into a GraphState dict.

    Inactive conditional branches emit an empty Data, so the first payload that
    actually carries state wins.
    """
    if payload is None:
        return {}
    items = payload if isinstance(payload, list) else [payload]
    for item in items:
        data = dict(getattr(item, "data", {}) or {})
        if data:
            return data
    return {}


def _switch(state, name, default=True):
    return bool((state.get("switches") or {}).get(name, default))


def _llm_text(llm, prompt):
    """Call the wired Language Model with a single prompt and return its text."""
    response = llm.invoke(prompt)
    content = getattr(response, "content", response)
    if isinstance(content, list):
        content = "".join(str(getattr(part, "text", part)) for part in content)
    return str(content or "").strip()


JSON_REPAIR_PROMPT = (
    "You are a JSON repair model. You receive a malformed or partially broken string and "
    "return a single, valid, complete JSON value.\n"
    "RULES:\n"
    "- Preserve all values from the raw input exactly - never fabricate data not present in it.\n"
    "- Each key must appear exactly once; if a key is duplicated, keep the last occurrence.\n"
    "- Output nothing outside the JSON value - no explanation, no comments, no code fences.\n\n"
    "RAW INPUT:\n"
)


def _parse_json_once(text):
    """Strip code fences, take the first balanced object/array. None when unrecoverable."""
    cleaned = re.sub(r"```[a-zA-Z]*", "", text or "").strip()
    start = next((i for i, ch in enumerate(cleaned) if ch in "[{"), -1)
    if start == -1:
        return None
    opener = cleaned[start]
    closer = "]" if opener == "[" else "}"
    depth = 0
    for index in range(start, len(cleaned)):
        if cleaned[index] == opener:
            depth += 1
        elif cleaned[index] == closer:
            depth -= 1
            if depth == 0:
                try:
                    return json.loads(cleaned[start:index + 1])
                except json.JSONDecodeError:
                    return None
    return None


def _parse_json(text, default, repair_llm=None):
    """Parse LLM JSON, falling back to the JSON-repair model when the heuristics fail.

    Stands in for fix_llm_output(): the cheap tiers first, then the repair model. An
    optional handle left unconnected resolves to "" rather than None, so the repair
    client is duck-typed rather than compared against None.
    """
    parsed = _parse_json_once(text)
    if parsed is not None:
        return parsed
    if hasattr(repair_llm, "invoke") and (text or "").strip():
        parsed = _parse_json_once(_llm_text(repair_llm, JSON_REPAIR_PROMPT + str(text)[:4000]))
        if parsed is not None:
            return parsed
    return default


def _rows(table):
    """Normalise a Knowledge / Memory Base result into a list of plain row dicts."""
    if table is None:
        return []
    items = table if isinstance(table, list) else [table]
    rows = []
    for item in items:
        if item is None:
            continue
        if hasattr(item, "to_dict") and hasattr(item, "columns"):  # DataFrame
            rows.extend(item.to_dict(orient="records"))
            continue
        data = getattr(item, "data", None)
        if isinstance(data, dict):
            rows.append(dict(data))
        elif isinstance(item, dict):
            rows.append(dict(item))
    return rows


def _flatten_row(row, default_source):
    """Knowledge row -> the flat chunk shape retrieve._flatten_chunks produces.

    Downstream nodes read 'similarity_score' and a top-level int 'chunk_seq'
    (NAC's run detection depends on it), so the shape is preserved exactly.
    """
    chunk = {
        "content": row.get("content") or row.get("text") or "",
        "source": row.get("source") or row.get("file_name") or row.get("file_path") or default_source,
        "similarity_score": float(row.get("_score") or row.get("similarity_score") or 0.0),
    }
    sequence = row.get("chunk_seq", row.get("doc_index"))
    if isinstance(sequence, bool):
        sequence = None
    if isinstance(sequence, int):
        chunk["chunk_seq"] = sequence
    elif isinstance(sequence, str) and sequence.strip().lstrip("-").isdigit():
        chunk["chunk_seq"] = int(sequence)
    elif isinstance(sequence, float) and float(sequence).is_integer():
        chunk["chunk_seq"] = int(sequence)
    return chunk


def _cosine(left, right):
    dot = sum(a * b for a, b in zip(left, right))
    left_norm = sum(a * a for a in left) ** 0.5
    right_norm = sum(b * b for b in right) ** 0.5
    if not left_norm or not right_norm:
        return 0.0
    return dot / (left_norm * right_norm)


def _jaccard(left, right):
    left_tokens = set(re.findall(r"\w+", (left or "").lower()))
    right_tokens = set(re.findall(r"\w+", (right or "").lower()))
    if not left_tokens or not right_tokens:
        return 0.0
    return len(left_tokens & right_tokens) / float(len(left_tokens | right_tokens))


def _embed(embeddings, texts):
    """Embed with the wired embeddings model; None falls the caller back to token overlap."""
    if not hasattr(embeddings, "embed_documents") or not texts:
        return None
    try:
        return embeddings.embed_documents([text or "" for text in texts])
    except Exception:  # noqa: BLE001 - similarity is an optimisation, never fatal
        return None


def _similarity_matrix(embeddings, contents):
    """Return (similarity(i, j), mode) - embedding cosine when available."""
    vectors = _embed(embeddings, contents)
    if vectors and len(vectors) == len(contents):
        return lambda i, j: _cosine(vectors[i], vectors[j]), "embeddings"
    return lambda i, j: _jaccard(contents[i], contents[j]), "token-overlap"


def _build_context(compressed_docs):
    """Context format used by generate_draft / check_answer_quality / generate_answer."""
    return "\n\n".join(
        "[{0}] {1}".format(index + 1, doc.get("content", ""))
        for index, doc in enumerate(compressed_docs)
    )


def _chunks_block(chunks):
    """Indexed chunk block for the judge prompts."""
    return "\n\n".join(
        "[{0}] [Source: {1}]\n{2}".format(index, chunk.get("source", "?"), chunk.get("content", ""))
        for index, chunk in enumerate(chunks)
    )


def _field(track):
    """documents -> 'document', learned_qa -> 'learned_qa' (matches GraphState keys)."""
    return "document" if track == "documents" else "learned_qa"

REDUNDANCY_JUDGE_PROMPT = 'You are validating proposed redundancy groups.\n\nYour task:\nFor each proposed group, decide whether all sentences in that group express the SAME FACT.\n\nCHUNKS:\n{chunks_block}\n\nPROPOSED GROUPS:\n{groups_block}\n\nA group is CONFIRMED only if:\n- all sentences have the same subject\n- all sentences make the same claim\n- all sentences have the same meaning\n- removing duplicate copies would NOT lose unique information\n\nIMPORTANT:\n- Same topic is NOT enough.\n- Related ideas are NOT enough.\n- Similar wording is NOT enough.\n- If one sentence adds a unique detail, the group is REJECTED.\n- If the subjects are different real-world entities, the group is REJECTED.\n- If meanings conflict or one sentence negates another, the group is REJECTED.\n\nBe STRICT. Be CONSERVATIVE. If unsure, REJECT the group.\n\nOUTPUT FORMAT:\nReturn ONLY a JSON array. One object per proposed group, in the same order as the input groups.\n\n[\n  {{"group_index": 0, "verdict": "CONFIRMED", "reason": "Same subject and same factual claim."}},\n  {{"group_index": 1, "verdict": "REJECTED", "reason": "Related topic but different facts."}}\n]\n\nThe first character of your response must be \'[\'.\nYour response will be parsed directly using json.loads().\nReturn ONLY the JSON array.\n'


class RagDcValidator(Component):
    display_name = "validate_DC_documents"
    description = (
        "validate_dc_* in dc.py. Judges each window's redundancy groups and records how many "
        "were confirmed and rejected. Observational, like the LangGraph node - the chunks DC "
        "produced are not modified."
    )
    icon = "shield-check"
    name = "RagDcValidator"

    inputs = [
        DataInput(name="state", display_name="State", is_list=True),
        HandleInput(
            name="llm",
            display_name="Judge Model",
            input_types=["LanguageModel"],
            required=True,
            info="judge_llm in llm_setup.py: temperature 0.0, 1024 output tokens.",
        ),
        HandleInput(
            name="repair_llm",
            display_name="JSON Repair Model",
            input_types=["LanguageModel"],
            required=False,
            info="Groq client used only to repair malformed JSON (temperature 0.0, 1024 tokens).",
        ),
        DropdownInput(
            name="track",
            display_name="Track",
            options=["documents", "learned_qa"],
            value="documents",
        ),
        MultilineInput(
            name="judge_prompt",
            display_name="Redundancy Judge Prompt",
            value=REDUNDANCY_JUDGE_PROMPT,
        ),
    ]

    outputs = [Output(display_name="State", name="state_out", method="validate")]

    def validate(self) -> Data:
        state = _state_of(self.state)
        windows = list(state.get("dc_groups_per_window_{0}".format(self.track)) or [])
        if not windows:
            self.status = "no redundancy groups to validate"
            return Data(data=state)

        summaries = []
        for index, entry in enumerate(windows):
            groups = entry.get("groups") or []
            prompt = self.judge_prompt.format(
                chunks_block=_chunks_block(entry.get("window_chunks") or []),
                groups_block=json.dumps([{"members": members} for members in groups], indent=2),
            )
            verdicts = _parse_json(_llm_text(self.llm, prompt), [], repair_llm=self.repair_llm)
            confirmed = sum(
                1 for item in verdicts
                if isinstance(item, dict) and str(item.get("verdict", "")).upper() == "CONFIRMED"
            )
            rejected = sum(
                1 for item in verdicts
                if isinstance(item, dict) and str(item.get("verdict", "")).upper() == "REJECTED"
            )
            summaries.append({"window": index, "confirmed": confirmed, "rejected": rejected})

        state["dc_validation_{0}".format(self.track)] = summaries
        self.status = "\n".join(
            "window {0}: confirmed={1}  rejected={2}".format(
                entry["window"], entry["confirmed"], entry["rejected"]
            )
            for entry in summaries
        )
        return Data(data=state)

