LBC_JUDGE_PROMPT = 'You are a compression-safety judge for a query-focused chunk compression step.\n\nA compression step received an ORIGINAL CHUNK and a USER QUERY, and produced a COMPRESSED CHUNK\nby removing sentences it deemed irrelevant to the query. Your job is to verify the compression\nis safe - it must not invent facts, and it must not discard sentences that are relevant to the query.\n\nUSER QUERY:\n{query}\n\nORIGINAL CHUNK (source: {source}):\n{original_content}\n\nCOMPRESSED CHUNK:\n{compressed_content}\n\nJUDGMENT RULES:\nRULE 1 - NO FABRICATION\nEvery sentence in the COMPRESSED CHUNK must be traceable (verbatim or as a clear paraphrase)\nto the ORIGINAL CHUNK.\n\nRULE 2 - NO RELEVANT FACTS LOST\nA sentence from the ORIGINAL CHUNK is a "lost relevant fact" only if BOTH conditions hold:\n  (a) It contains information that directly helps answer the USER QUERY.\n  (b) It is absent from the COMPRESSED CHUNK (neither verbatim nor as a paraphrase).\n\nRULE 3 - PARAPHRASE = PRESENT\nIf the compressed chunk expresses a fact in different words from the original, the fact is\nstill present. Do not list it as lost.\n\nVERDICT:\n- "SAFE"            : no fabrications and no relevant facts were lost\n- "OVER_COMPRESSED" : at least one query-relevant fact was dropped (no fabrications)\n- "FABRICATED"      : at least one sentence in the compressed output has no source support\n- "UNKNOWN"         : cannot determine (malformed input)\n\nReturn ONLY a JSON object - no markdown, no prose, no code fences:\n{{\n  "verdict": "SAFE" | "OVER_COMPRESSED" | "FABRICATED" | "UNKNOWN",\n  "fabricated_claims":   ["<sentence from compressed chunk with no source support>", ...],\n  "lost_relevant_facts": ["<query-relevant sentence from original that was dropped>", ...],\n  "overall_reason": "<one or two sentences>"\n}}\nIf both lists are empty, return empty arrays.'


class RagLbcValidator(Component):
    display_name = "validate_LBC_documents"
    description = (
        "validate_lbc_* in lbc.py. Judges every accepted compression for safety and records "
        "the verdicts. Always present so combine_tracks has a fixed predecessor, and a "
        "pass-through when ENABLE_COMPRESSION_VALIDATION is off. Observational, like the "
        "LangGraph node - the compressed chunks are not modified."
    )
    icon = "shield-check"
    name = "RagLbcValidator"

    inputs = [
        DataInput(name="state", display_name="State", is_list=True),
        HandleInput(
            name="llm",
            display_name="Judge Model",
            input_types=["LanguageModel"],
            required=True,
            info="judge_llm in llm_setup.py: temperature 0.0, 1024 output tokens.",
        ),
        HandleInput(
            name="repair_llm",
            display_name="JSON Repair Model",
            input_types=["LanguageModel"],
            required=False,
            info="Groq client used only to repair malformed JSON (temperature 0.0, 1024 tokens).",
        ),
        DropdownInput(
            name="track",
            display_name="Track",
            options=["documents", "learned_qa"],
            value="documents",
        ),
        MultilineInput(name="judge_prompt", display_name="LBC Judge Prompt", value=LBC_JUDGE_PROMPT),
    ]

    outputs = [Output(display_name="State", name="state_out", method="validate")]

    def validate(self) -> Data:
        state = _state_of(self.state)
        pairs = list(state.get("lbc_validation_pairs_{0}".format(self.track)) or [])

        if not _switch(state, "ENABLE_COMPRESSION_VALIDATION"):
            self.status = "compression validation disabled - passing through"
            return Data(data=state)
        if not pairs:
            self.status = "no compressed chunks to validate"
            return Data(data=state)

        verdicts = []
        for index, pair in enumerate(pairs):
            original = pair.get("original") or {}
            compressed = pair.get("compressed") or {}
            prompt = self.judge_prompt.format(
                query=state.get("query") or state.get("user_input") or "",
                source=original.get("source", "?"),
                original_content=original.get("content", ""),
                compressed_content=compressed.get("content", ""),
            )
            result = _parse_json(_llm_text(self.llm, prompt), {}, repair_llm=self.repair_llm)
            verdicts.append(
                {
                    "chunk": index,
                    "verdict": str((result or {}).get("verdict", "UNKNOWN")).upper()
                    if isinstance(result, dict) else "UNKNOWN",
                    "fabricated_claims": (result or {}).get("fabricated_claims") or []
                    if isinstance(result, dict) else [],
                    "lost_relevant_facts": (result or {}).get("lost_relevant_facts") or []
                    if isinstance(result, dict) else [],
                }
            )

        state["lbc_validation_{0}".format(self.track)] = verdicts
        self.status = "\n".join(
            "chunk {0}: verdict={1}  fabricated={2}  lost_relevant={3}".format(
                entry["chunk"], entry["verdict"], len(entry["fabricated_claims"]),
                len(entry["lost_relevant_facts"]),
            )
            for entry in verdicts
        )
        return Data(data=state)

