GENERATE_DRAFT_PROMPT = 'You are drafting a working answer to a user\'s question using ONLY the retrieved context below.\nThis draft will be reviewed and rewritten in a later step, but it must already be honest and grounded -\nthe later step trims and rephrases, it does not fact-check from scratch.\n\nYou are NOT a general knowledge assistant.\nYou are NOT filling gaps from memory or training data.\nYou are NOT completing a plausible-sounding list because the topic invites one.\nYou are ONLY reporting what the CONTEXT states.\n\nQUESTION:\n{query}\n\nCONTEXT:\n{context}\n\nA claim may appear in the draft only if:\n- it is stated in the CONTEXT, verbatim or as a direct paraphrase\n- it is not an inference, extrapolation, or generalization beyond what the CONTEXT says\n- it is not a "typical" or "common" fact about the topic that you know but the CONTEXT does not state\n\nIMPORTANT:\n- Length must track evidence, not effort. A single relevant chunk gets a short draft, not a padded one.\n- Do not pad a thin answer with plausible-sounding related facts to make it feel complete.\n- If the context only partially covers the question, say so in the draft instead of glossing over it.\n- If the context does not meaningfully address the question, say so directly instead of guessing.\n- Mentioning a topic is NOT the same as supporting a specific claim about it.\n- If the context implies a category exists (e.g. "safety features") without listing members, do NOT invent the members.\n- If sources disagree, report the disagreement - do not silently pick one.\n\nBe CONSERVATIVE about what counts as supported. If unsure whether a claim is supported, leave it out.\n\nOUTPUT FORMAT:\n- Plain prose, no headings, no bullet lists.\n- Keep the draft as short as the evidence allows - do not stretch it to sound complete.\n- Cite claims inline as [Source: filename] immediately after the sentence they support.\n- Do not restate the question.\n\nDraft only from the CONTEXT above. Match length and confidence to what it actually supports.\n'


class RagGenerateDraft(Component):
    display_name = "generate_draft"
    description = (
        "generate_draft.py. Drafts an answer from compressed_docs against the original "
        "user_input, using the numbered context format the answer pipeline shares, then "
        "routes to the quality check and then generate_answer."
    )
    icon = "pencil-line"
    name = "RagGenerateDraft"

    ROUTES = ("to_quality",)

    inputs = [
        DataInput(name="state", display_name="State", is_list=True),
        HandleInput(
            name="llm",
            display_name="Generation Model",
            input_types=["LanguageModel"],
            required=True,
            info="llm in llm_setup.py: temperature 0.1, 2048 output tokens.",
        ),
        MultilineInput(name="draft_prompt", display_name="Draft Prompt", value=GENERATE_DRAFT_PROMPT),
    ]

    outputs = [
        Output(display_name="To Quality Check", name="to_quality", method="route_quality"),
    ]

    def _run(self):
        cached = getattr(self, "_drafted_state", None)
        if cached is not None:
            return cached
        state = _state_of(self.state)
        if not state.get("draft"):
            prompt = self.draft_prompt.format(
                query=state.get("user_input", ""),
                context=_build_context(state.get("compressed_docs") or []),
            )
            state["draft"] = _llm_text(self.llm, prompt)
        self._drafted_state = state
        return state

    def _emit(self, target):
        state = self._run()
        route = "to_quality"
        if route != target:
            self.stop(target)
            return Data(data={})
        for other in self.ROUTES:
            if other != target:
                self.stop(other)
        self.status = state.get("draft", "")
        return Data(data=state)

    def route_quality(self) -> Data:
        return self._emit("to_quality")

