    VALID_VERDICTS = ("GROUNDED", "PARTIALLY_FABRICATED", "OVERCLAIMED", "OFF_TOPIC", "UNKNOWN")

    inputs = [
        DataInput(name="state", display_name="State", is_list=True),
        HandleInput(
            name="llm",
            display_name="Judge Model",
            input_types=["LanguageModel"],
            required=True,
            info="judge_llm in llm_setup.py: temperature 0.0, 1024 output tokens.",
        ),
        HandleInput(
            name="repair_llm",
            display_name="JSON Repair Model",
            input_types=["LanguageModel"],
            required=False,
            info="Groq client used only to repair malformed JSON (temperature 0.0, 1024 tokens).",
        ),
        MultilineInput(name="grounding_prompt", display_name="Grounding Prompt", value=GROUNDING_PROMPT),
    ]

    outputs = [
        Output(display_name="To Answer", name="to_answer", method="route_answer"),
    ]

    def _run(self):
        cached = getattr(self, "_checked_state", None)
        if cached is not None:
            return cached
        state = _state_of(self.state)
        if not state.get("quality_verdict"):
            prompt = self.grounding_prompt.format(
                query=state.get("user_input", ""),
                context=_build_context(state.get("compressed_docs") or []),
                answer=state.get("draft", ""),
            )
            result = _parse_json(_llm_text(self.llm, prompt), {}, repair_llm=self.repair_llm)
            if isinstance(result, dict) and result:
                verdict = str(result.get("verdict") or "UNKNOWN").upper().strip()
                if verdict not in self.VALID_VERDICTS:
                    verdict = "UNKNOWN"
                state["quality_verdict"] = verdict
                state["quality_reason"] = str(result.get("overall_reason") or "")
                state["quality_unsupported_claims"] = result.get("unsupported_claims") or []
            else:
                state["quality_verdict"] = "UNKNOWN"
                state["quality_reason"] = "judge response was not valid JSON"
        self._checked_state = state
        return state

    def _route(self, state):
        # Keep this export acyclic. A non-grounded verdict is retained in
        # state so generate_answer can report quality and safely use the draft.
        return "to_answer"

    def _emit(self, target):
        state = self._run()
        route = self._route(state)
        if route != target:
            self.stop(target)
            return Data(data={})
        for other in self.ROUTES:
            if other != target:
                self.stop(other)
        self.status = "verdict={0} unsupported_claims={1} route={2}\n{3}".format(
            state.get("quality_verdict"),
            len(state.get("quality_unsupported_claims") or []),
            route,
            state.get("quality_reason", ""),
        )
        return Data(data=state)

    def route_answer(self) -> Data:
        return self._emit("to_answer")

import json
import re

from lfx.custom.custom_component.component import Component
from lfx.io import (
    BoolInput,
    DataInput,
    DropdownInput,
    FloatInput,
    HandleInput,
    IntInput,
    MessageInput,
    MultilineInput,
    Output,
    StrInput,
)
from lfx.schema.data import Data
from lfx.schema.dataframe import DataFrame
from lfx.schema.message import Message


def _state_of(payload):
    """Unwrap a Langflow Data payload (or list of them) into a GraphState dict.

    Inactive conditional branches emit an empty Data, so the first payload that
    actually carries state wins.
    """
    if payload is None:
        return {}
    items = payload if isinstance(payload, list) else [payload]
    for item in items:
        data = dict(getattr(item, "data", {}) or {})
        if data:
            return data
    return {}


def _switch(state, name, default=True):
    return bool((state.get("switches") or {}).get(name, default))


def _llm_text(llm, prompt):
    """Call the wired Language Model with a single prompt and return its text."""
    response = llm.invoke(prompt)
    content = getattr(response, "content", response)
    if isinstance(content, list):
        content = "".join(str(getattr(part, "text", part)) for part in content)
    return str(content or "").strip()


JSON_REPAIR_PROMPT = (
    "You are a JSON repair model. You receive a malformed or partially broken string and "
    "return a single, valid, complete JSON value.\n"
    "RULES:\n"
    "- Preserve all values from the raw input exactly - never fabricate data not present in it.\n"
    "- Each key must appear exactly once; if a key is duplicated, keep the last occurrence.\n"
    "- Output nothing outside the JSON value - no explanation, no comments, no code fences.\n\n"
    "RAW INPUT:\n"
)


def _parse_json_once(text):
    """Strip code fences, take the first balanced object/array. None when unrecoverable."""
    cleaned = re.sub(r"```[a-zA-Z]*", "", text or "").strip()
    start = next((i for i, ch in enumerate(cleaned) if ch in "[{"), -1)
    if start == -1:
        return None
    opener = cleaned[start]
    closer = "]" if opener == "[" else "}"
    depth = 0
    for index in range(start, len(cleaned)):
        if cleaned[index] == opener:
            depth += 1
        elif cleaned[index] == closer:
            depth -= 1
            if depth == 0:
                try:
                    return json.loads(cleaned[start:index + 1])
                except json.JSONDecodeError:
                    return None
    return None


def _parse_json(text, default, repair_llm=None):
    """Parse LLM JSON, falling back to the JSON-repair model when the heuristics fail.

    Stands in for fix_llm_output(): the cheap tiers first, then the repair model. An
    optional handle left unconnected resolves to "" rather than None, so the repair
    client is duck-typed rather than compared against None.
    """
    parsed = _parse_json_once(text)
    if parsed is not None:
        return parsed
    if hasattr(repair_llm, "invoke") and (text or "").strip():
        parsed = _parse_json_once(_llm_text(repair_llm, JSON_REPAIR_PROMPT + str(text)[:4000]))
        if parsed is not None:
            return parsed
    return default


def _rows(table):
    """Normalise a Knowledge / Memory Base result into a list of plain row dicts."""
    if table is None:
        return []
    items = table if isinstance(table, list) else [table]
    rows = []
    for item in items:
        if item is None:
            continue
        if hasattr(item, "to_dict") and hasattr(item, "columns"):  # DataFrame
            rows.extend(item.to_dict(orient="records"))
            continue
        data = getattr(item, "data", None)
        if isinstance(data, dict):
            rows.append(dict(data))
        elif isinstance(item, dict):
            rows.append(dict(item))
    return rows


def _flatten_row(row, default_source):
    """Knowledge row -> the flat chunk shape retrieve._flatten_chunks produces.

    Downstream nodes read 'similarity_score' and a top-level int 'chunk_seq'
    (NAC's run detection depends on it), so the shape is preserved exactly.
    """
    chunk = {
        "content": row.get("content") or row.get("text") or "",
        "source": row.get("source") or row.get("file_name") or row.get("file_path") or default_source,
        "similarity_score": float(row.get("_score") or row.get("similarity_score") or 0.0),
    }
    sequence = row.get("chunk_seq", row.get("doc_index"))
    if isinstance(sequence, bool):
        sequence = None
    if isinstance(sequence, int):
        chunk["chunk_seq"] = sequence
    elif isinstance(sequence, str) and sequence.strip().lstrip("-").isdigit():
        chunk["chunk_seq"] = int(sequence)
    elif isinstance(sequence, float) and float(sequence).is_integer():
        chunk["chunk_seq"] = int(sequence)
    return chunk


def _cosine(left, right):
    dot = sum(a * b for a, b in zip(left, right))
    left_norm = sum(a * a for a in left) ** 0.5
    right_norm = sum(b * b for b in right) ** 0.5
    if not left_norm or not right_norm:
        return 0.0
    return dot / (left_norm * right_norm)


def _jaccard(left, right):
    left_tokens = set(re.findall(r"\w+", (left or "").lower()))
    right_tokens = set(re.findall(r"\w+", (right or "").lower()))
    if not left_tokens or not right_tokens:
        return 0.0
    return len(left_tokens & right_tokens) / float(len(left_tokens | right_tokens))


def _embed(embeddings, texts):
    """Embed with the wired embeddings model; None falls the caller back to token overlap."""
    if not hasattr(embeddings, "embed_documents") or not texts:
        return None
    try:
        return embeddings.embed_documents([text or "" for text in texts])
    except Exception:  # noqa: BLE001 - similarity is an optimisation, never fatal
        return None


def _similarity_matrix(embeddings, contents):
    """Return (similarity(i, j), mode) - embedding cosine when available."""
    vectors = _embed(embeddings, contents)
    if vectors and len(vectors) == len(contents):
        return lambda i, j: _cosine(vectors[i], vectors[j]), "embeddings"
    return lambda i, j: _jaccard(contents[i], contents[j]), "token-overlap"


def _build_context(compressed_docs):
    """Context format used by generate_draft / check_answer_quality / generate_answer."""
    return "\n\n".join(
        "[{0}] {1}".format(index + 1, doc.get("content", ""))
        for index, doc in enumerate(compressed_docs)
    )


def _chunks_block(chunks):
    """Indexed chunk block for the judge prompts."""
    return "\n\n".join(
        "[{0}] [Source: {1}]\n{2}".format(index, chunk.get("source", "?"), chunk.get("content", ""))
        for index, chunk in enumerate(chunks)
    )


def _field(track):
    """documents -> 'document', learned_qa -> 'learned_qa' (matches GraphState keys)."""
    return "document" if track == "documents" else "learned_qa"

GENERATE_ANSWER_PROMPT = 'You are answering a user\'s question using ONLY the retrieved context below.\n\nYour task:\nDecide how much of the question the CONTEXT actually supports, then write an answer whose length\nand confidence matches that support.\n\nYou are NOT a general knowledge assistant.\nYou are NOT filling gaps from memory or training data.\nYou are NOT completing a plausible-sounding list because the topic invites one.\nYou are ONLY reporting what the CONTEXT states.\n\nQUESTION:\n{query}\n\nCONTEXT:\n{context}\n\nBefore answering, classify the CONTEXT\'s coverage of the QUESTION:\n- FULL - the context directly answers all parts of the question.\n- PARTIAL - the context answers some parts, or touches the topic without giving complete detail.\n- INSUFFICIENT - the context does not meaningfully address the question.\n\nA claim may appear in the answer only if:\n- it is stated in the CONTEXT, verbatim or as a direct paraphrase\n- it is not an inference, extrapolation, or generalization beyond what the CONTEXT says\n- it is not a "typical" or "common" fact about the topic that you know but the CONTEXT does not state\n\nIMPORTANT:\n- A single relevant chunk is NOT license to produce a full, itemized answer.\n- Do not pad a thin answer with plausible-sounding related facts to make it feel complete.\n- Do not upgrade a PARTIAL coverage answer to sound like FULL coverage.\n- Mentioning a topic is NOT the same as supporting a specific claim about it.\n- If the context implies a category exists (e.g. "safety features") without listing members, do NOT invent the members.\n- If sources disagree, report the disagreement - do not silently pick one.\n- Length must track evidence: little context means a short answer, not a long one.\n\nBe HONEST about coverage. Be CONSERVATIVE about what counts as supported.\nIf unsure whether a claim is supported, leave it out.\n\nOUTPUT FORMAT:\n- Plain prose, no headings, no bullet lists.\n- State coverage honestly within the answer itself when it is PARTIAL or INSUFFICIENT.\n- Cite claims inline as [Source: filename] immediately after the sentence they support.\n- If coverage is INSUFFICIENT, say so directly instead of producing an answer.\n- Do not restate the question. Do not add closing summaries or caveats beyond what coverage honesty requires.\n\nAnswer only from the CONTEXT above. Match your confidence and length to what it actually supports.\n'

GENERATE_ANSWER_FROM_DRAFT_PROMPT = "You are finalizing an answer to a user's question using ONLY the retrieved context below.\nAn answer draft was already produced from this same context - use it as working material to improve\nclarity and organization, but the CONTEXT remains the sole source of truth for what may be claimed.\n\nQUESTION:\n{query}\n\nCONTEXT:\n{context}\n\nDRAFT ANSWER (working material - not the source of truth):\n{draft}\n\nYour task:\n- Rewrite the draft into the final answer, keeping only claims that are supported by the CONTEXT above.\n- Drop any claim in the draft that is not grounded in the CONTEXT, even if the draft stated it plainly.\n- Do not add claims beyond what the CONTEXT supports, whether or not the draft mentioned them.\n- Match the answer's length and confidence to what the CONTEXT actually supports - a thin context\n  means a short, honest answer, not a long one padded from the draft's phrasing.\n- If sources disagree, report the disagreement - do not silently pick one.\n\nOUTPUT FORMAT:\n- Plain prose, no headings, no bullet lists.\n- State coverage honestly when it is partial or insufficient.\n- Cite claims inline as [Source: filename] immediately after the sentence they support.\n- Do not restate the question. Do not add closing summaries or caveats beyond what coverage honesty requires.\n\nAnswer only from the CONTEXT above, using the draft only to guide phrasing and structure.\n"


class RagGenerateAnswer(Component):
    description = (
        "generate_answer.py. Uses the from-draft prompt when a draft exists and the direct "
        "prompt otherwise; if the final synthesis call fails it falls back to the draft "
        "rather than returning nothing. Quality is derived from the judge verdict. Always "
        "emits the answer; the distillation branch is taken only when "
        "ENABLE_AUTO_DISTILLATION is on."
    )
    display_name = "generate_answer"
    icon = "message-square"
    name = "RagGenerateAnswer"

    PASS_VERDICT = "GROUNDED"

    inputs = [
        DataInput(name="state", display_name="State", is_list=True),
        HandleInput(
            name="llm",
            display_name="Generation Model",
            input_types=["LanguageModel"],
            required=True,
            info="llm in llm_setup.py: temperature 0.1, 2048 output tokens.",
        ),
        MultilineInput(name="answer_prompt", display_name="Answer Prompt", value=GENERATE_ANSWER_PROMPT),
        MultilineInput(
            name="answer_from_draft_prompt",
            display_name="Answer From Draft Prompt",
            value=GENERATE_ANSWER_FROM_DRAFT_PROMPT,
        ),
    ]

    outputs = [
        Output(display_name="Answer", name="answer", method="build_answer"),
        Output(display_name="To Distillation", name="to_distill", method="route_distillation"),
    ]

    def _run(self):
        cached = getattr(self, "_answer_state", None)
        if cached is not None:
            return cached
        state = _state_of(self.state)
        if not state.get("answer"):
            user_input = state.get("user_input", "")
            context = _build_context(state.get("compressed_docs") or [])
            draft = state.get("draft")
            if draft:
                prompt = self.answer_from_draft_prompt.format(
                    query=user_input, context=context, draft=draft
                )
            else:
                prompt = self.answer_prompt.format(query=user_input, context=context)
            try:
                answer = _llm_text(self.llm, prompt)
            except Exception as exc:
                if draft:
                    # A grounded draft is a safe fallback when final polishing fails.
                    answer = draft
                else:
                    raise RuntimeError(
                        f"Final answer generation failed: {type(exc).__name__}: {exc}"
                    ) from exc
            if not answer and draft:
                answer = draft
            if not answer:
                raise ValueError(
                    "No final answer was generated: both the LLM response and draft are empty."
                )
            state["answer"] = answer

            verdict = str(state.get("quality_verdict") or "").upper().strip()
            state["quality"] = "OK" if (not verdict or verdict == self.PASS_VERDICT) else verdict
            state["sources"] = [
                {"source": chunk.get("source", "?")} for chunk in (state.get("compressed_docs") or [])
            ]
        self._answer_state = state
        return state

    def build_answer(self) -> Message:
        state = self._run()
        self.status = "quality={0}\n\n{1}".format(state.get("quality", "OK"), state.get("answer", ""))
        return Message(text=state.get("answer", ""))

    def route_distillation(self) -> Data:
        state = self._run()
        if not _switch(state, "ENABLE_AUTO_DISTILLATION", default=False):
            self.stop("to_distill")
            return Data(data={})
        return Data(data=state)
